/* @lc app=leetcode id=2332 lang=kotlin */ class Solution { fun latestTimeCatchTheBus(buses: IntArray, passengers: IntArray, capacity: Int): Int = passengers.sorted().let { p -> buses.sorted().fold(0 to 0) { (i, _), b -> generateSequence(i) { it + 1 }.takeWhile { it < p.size && p[it] <= b && it - i < capacity }.count().let { c -> (i + c) to (if (c < capacity) b else p[i + c - 1]) } }.second.let { cand -> p.toSet().let { s -> generateSequence(cand) { it - 1 }.first { it !in s } } } } }